KG42.register("clusters-6cd09a9bfa946851aa8027c2",{"id":"27-multiple_microgrid_trading::v142-d-CL004","paper":"27-multiple_microgrid_trading","label":"Microgrid purchase-and-sale participation permission","record":{"cluster_id":"v142-d-CL004","label":"Microgrid purchase-and-sale participation permission","market_meaning":"Interconnected island microgrids may purchase energy as permitted by the model; microgrids with local generation capability may sell energy in permitted directions. Purchase and sale roles may coexist; energy cannot be exchanged in directions without a connection.","mechanism_ids":["v141-a-M01"],"market_types":["DEM"],"process_stages":["participation"],"scope_disposition":"compatible","scope_explanation":"The two chains jointly explain the purchase and sale permission of the same system and do not interpret consumer and prosumer as mutually exclusive identities. R009 retains the generation capability scope but does not thereby require a seller to generate in the current period; the existence of a connection also does not guarantee positive transaction volume.","assembly_status":"assembled","boundary_rationale":"Purchase and sale permissions jointly define the microgrid's participation roles; this scope does not include formal admission procedures, quantity optimization, or settlement procedures that are not provided.","chain_bindings":[{"chain_id":"v141-c-R008","ownership":"primary","role":"core","rationale":"Retains the non-mathematical statement of purchase permission and does not fabricate an electricity-purchase variable merely because an x object is missing."},{"chain_id":"v141-c-R009","ownership":"primary","role":"core","rationale":"Supplements the sale permission, directed connection conditions, and self-connection conventions within its scope."}],"connections":[{"connection_id":"v142-d-CL004-CN01","from_chain_id":"v141-c-R008","to_chain_id":"v141-c-R009","kind":"complementary_scope","from_refs":["v141-c-R008::phi::v141-c-R008-C001"],"to_refs":["v141-c-R009::phi::v141-c-R009-C001"],"evidence_ids":["v141-b-g04-e004","v141-b-g06-e006"],"rationale":"The same system model permits microgrids both to purchase and to sell energy, forming a complementary role scope; it does not declare identity exclusivity or a derivation edge between the two permissions."}],"object_mappings":[],"gaps":[{"gap_id":"v142-d-CL004-G01","category":"upstream_missing","description":"The source gives only a model-level may be allowed permission, without complete eligibility determination or admission procedures; having a connection is not sufficient evidence of other institutional qualifications.","chain_ids":["v141-c-R008","v141-c-R009"],"object_refs":["v141-c-R008::phi::v141-c-R008-C001","v141-c-R009::phi::v141-c-R009-C001"],"evidence_ids":["v141-b-g04-e004","v141-b-g06-e006"],"proposal_ids":[],"required_work":"If institutionalized admission rules are required, supplement clear sources and conditions; the current candidate maintains the purchase-and-sale permission scope."},{"gap_id":"v142-d-CL004-G02","category":"scope_conflict","description":"Case 5 allows buying for resale without generating in the current period, so R009's generation capability scope cannot be extrapolated into a restriction that all sellers must generate in the current period.","chain_ids":["v141-c-R009"],"object_refs":["v141-c-R009::phi::v141-c-R009-C001"],"evidence_ids":["v141-b-g04-e004","v141-b-g34-e034"],"proposal_ids":[],"required_work":"Manually check the distinction between participation labels, generation capability, and current-period generation activity; retain the original chain scope and do not add general eligibility restrictions."},{"gap_id":"v142-d-CL004-G03","category":"unverified_source","description":"The purchase-and-sale permission and directional conditions are based on unaudited B citations; the current status remains unverified.","chain_ids":["v141-c-R008","v141-c-R009"],"object_refs":[],"evidence_ids":["v141-b-g04-e004","v141-b-g06-e006"],"proposal_ids":[],"required_work":"Manually verify the permission wording and applicable subjects; assembly does not mean the admission regime or source has been approved."}]},"rule_refs":["27-multiple_microgrid_trading::v141-c-R008","27-multiple_microgrid_trading::v141-c-R009"],"unresolved_rule_refs":[],"node_ids":["COMP-7f5e3dcddfa1014c","COMP-e80c3b7a1946ecd1"]});
